#!/usr/bin/env python3
"""Builds one paste-and-go Spicetify extension. stdlib only."""
from pathlib import Path
import json
root = Path(__file__).resolve().parent.parent
src = root / 'src'
css = (src / 'style.css').read_text(encoding='utf-8')
core = (src / 'core.js').read_text(encoding='utf-8')
app = (src / 'extension.js').read_text(encoding='utf-8')
output = (
    '/* BratStage v4.0.0 — MIT — Original code, not copied from reference repo.\n'
    ' * Generated by scripts/build.py | Source: src/{core.js,style.css,extension.js}\n */\n'
    + 'window.__BRATSTAGE_CSS__ = ' + json.dumps(css, ensure_ascii=False) + ';\n\n'
    + core + '\n\n' + app
)
(root / 'bratstage.js').write_text(output, encoding='utf-8')
print('Built bratstage.js', (root / 'bratstage.js').stat().st_size, 'bytes')
